<script setup lang="ts">import {computed} from 'vue';import type {BayesNode} from '../types/domain';const props=withDefaults(defineProps<{nodes:BayesNode[],evidence?:Record<string,number>,target?:string}>(),{evidence:()=>({}),target:''});const layout=computed(()=>{const levels:Record<string,number>={};const level=(id:string):number=>{if(levels[id]!==undefined)return levels[id];const node=props.nodes.find(n=>n.node_id===id)!;return levels[id]=node.parents.length?1+Math.max(...node.parents.map(level)):0};props.nodes.forEach(n=>level(n.node_id));const max=Math.max(...Object.values(levels),1);return props.nodes.map(n=>{const peers=props.nodes.filter(p=>levels[p.node_id]===levels[n.node_id]);return {...n,x:95+levels[n.node_id]/max*455,y:45+(peers.findIndex(p=>p.node_id===n.node_id)+.5)*320/peers.length}})});const edges=computed(()=>layout.value.flatMap(n=>n.parents.map(p=>({from:layout.value.find(r=>r.node_id===p)!,to:n}))));</script><template><div class="network-diagram"><svg viewBox="0 0 650 410" role="img" aria-label="给定研修模型的二元有向无环图"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z"/></marker></defs><path v-for="(e,i) in edges" :key="i" :d="'M'+(e.from.x+59)+' '+e.from.y+' C'+(e.from.x+100)+' '+e.from.y+','+(e.to.x-100)+' '+e.to.y+','+(e.to.x-60)+' '+e.to.y" class="network-edge" marker-end="url(#arrow)"/><g v-for="n in layout" :key="n.node_id" :class="['network-node',{observed:evidence[n.node_id]!==undefined,target:n.node_id===target}]"><rect :x="n.x-59" :y="n.y-25" width="118" height="50"/><text :x="n.x" :y="n.y-4" text-anchor="middle">{{n.node_id}}{{evidence[n.node_id]!==undefined?' = '+evidence[n.node_id]:''}}</text><text :x="n.x" :y="n.y+14" text-anchor="middle" class="node-label">{{n.label}}{{n.node_id===target?' / Q':''}}</text></g><text x="20" y="400" class="diagram-note">深色＝已观测证据　赭框＝查询目标　箭头来自给定DAG，不表示数据发现的因果。</text></svg></div></template>
